#include <fstream>
#include <vector>
#include <algorithm>
#include <cstdint>
using namespace std;
// Nonnegative exact integers in base 10^9. No floating-point approximation.
struct Big {
    static const uint32_t BASE = 1000000000;
    vector<uint32_t> d;
    Big(uint64_t x = 0) {
        do { d.push_back((uint32_t)(x % BASE)); x /= BASE; } while (x);
    }
    void trim() { while (d.size() > 1 && d.back() == 0) d.pop_back(); }
    Big times(uint32_t x) const {
        Big r; r.d.resize(d.size()); uint64_t carry = 0;
        for (size_t j = 0; j < d.size(); ++j) {
            uint64_t value = (uint64_t)d[j] * x + carry;
            r.d[j] = (uint32_t)(value % BASE); carry = value / BASE;
        }
        if (carry) r.d.push_back((uint32_t)carry);
        r.trim(); return r;
    }
    Big plus(const Big &b) const {
        Big r; r.d.resize(max(d.size(), b.d.size())); uint64_t carry = 0;
        for (size_t j = 0; j < r.d.size(); ++j) {
            uint64_t value = carry + (j < d.size() ? d[j] : 0) + (j < b.d.size() ? b.d[j] : 0);
            r.d[j] = (uint32_t)(value % BASE); carry = value / BASE;
        }
        if (carry) r.d.push_back((uint32_t)carry);
        return r;
    }
    Big minus(const Big &b) const {
        Big r; r.d.resize(d.size()); int64_t borrow = 0;
        for (size_t j = 0; j < d.size(); ++j) {
            int64_t value = (int64_t)d[j] - (j < b.d.size() ? b.d[j] : 0) - borrow;
            borrow = value < 0; if (borrow) value += BASE;
            r.d[j] = (uint32_t)value;
        }
        r.trim(); return r;
    }
    bool operator<(const Big &b) const {
        if (d.size() != b.d.size()) return d.size() < b.d.size();
        for (size_t j = d.size(); j-- > 0;) if (d[j] != b.d[j]) return d[j] < b.d[j];
        return false;
    }
};
void solve(istream &in, ostream &out) {
    int n; in >> n;
    vector<uint32_t> times, distances;
    for (int j = 0; j < n; ++j) {
        char kind; uint32_t x; in >> kind >> x;
        (kind == 'T' ? times : distances).push_back(x);
    }
    sort(times.begin(), times.end()); sort(distances.begin(), distances.end());
    size_t ti = 0, di = 0; uint32_t inverseSpeed = 1;
    Big denominator(1), elapsed(0), position(0);
    while (ti < times.size() || di < distances.size()) {
        bool useTime = di == distances.size();
        Big timeGap, distanceGap;
        if (ti < times.size()) timeGap = denominator.times(times[ti]).minus(elapsed);
        if (di < distances.size()) distanceGap = denominator.times(distances[di]).minus(position);
        if (ti < times.size() && di < distances.size()) useTime = !(distanceGap.times(inverseSpeed) < timeGap);
        if (useTime) {
            position = position.times(inverseSpeed).plus(timeGap);
            denominator = denominator.times(inverseSpeed);
            elapsed = denominator.times(times[ti++]);
        } else {
            elapsed = elapsed.plus(distanceGap.times(inverseSpeed));
            position = denominator.times(distances[di++]);
        }
        ++inverseSpeed;
    }
    Big finalNumerator = elapsed.plus(denominator.times(1000).minus(position).times(inverseSpeed));
    Big twiceFinal = finalNumerator.times(2);
    uint32_t low = 0, high = 1000 * (n + 1) + 1;
    while (low + 1 < high) {
        uint32_t middle = low + (high - low) / 2;
        if (!(twiceFinal < denominator.times(2 * middle - 1))) low = middle;
        else high = middle;
    }
    out << low << '\n';
}
int main() {
    ifstream in("slowdown.in");
    ofstream out("slowdown.out");
    solve(in, out);
    return 0;
}
