#include <fstream>
#include <vector>
#include <algorithm>
using namespace std;
int skill[12], best;
void assignTeams(int mask, vector<int> &sums) {
    if (sums.size() == 4) {
        best = min(best, *max_element(sums.begin(), sums.end()) - *min_element(sums.begin(), sums.end()));
        return;
    }
    int first = 0;
    while (mask & (1 << first)) ++first;
    for (int a = first + 1; a < 12; ++a) if (!(mask & (1 << a))) {
        for (int b = a + 1; b < 12; ++b) if (!(mask & (1 << b))) {
            sums.push_back(skill[first] + skill[a] + skill[b]);
            assignTeams(mask | (1 << first) | (1 << a) | (1 << b), sums);
            sums.pop_back();
        }
    }
}
void solve(istream &in, ostream &out) {
    for (int &x : skill) in >> x;
    best = 3000000;
    vector<int> sums;
    assignTeams(0, sums);
    out << best << '\n';
}
int main() {
    ifstream in("bteams.in");
    ofstream out("bteams.out");
    solve(in, out);
    return 0;
}
